import{_ as s,o as t,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Raccourcis personnalisés de barre latérale","description":"Créer des liens UIX vers des pages Home Assistant et des sites web.","frontmatter":{"title":"Raccourcis personnalisés de barre latérale","description":"Créer des liens UIX vers des pages Home Assistant et des sites web."},"headers":[],"relativePath":"fr/projects/uix/extras/custom-sidebar-panels.md","filePath":"fr/projects/uix/extras/custom-sidebar-panels.md","lastUpdated":1793890041000}'),n={name:"fr/projects/uix/extras/custom-sidebar-panels.md"};function o(i,e,l,c,u,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="raccourcis-personnalises-de-barre-laterale" tabindex="-1">Raccourcis personnalisés de barre latérale <a class="header-anchor" href="#raccourcis-personnalises-de-barre-laterale" aria-label="Permalink to &quot;Raccourcis personnalisés de barre latérale&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">UIX 9.0.0</p><p>Les raccourcis internes et externes ainsi que <strong>Open in new tab</strong> font partie de la version stable <strong>9.0.0</strong> et nécessitent <strong>Home Assistant 2026.11.0 ou ultérieur</strong>.</p></div><p>UIX peut ajouter des entrées à la barre latérale de Home Assistant pour ouvrir une autre page Home Assistant ou un site web. Cela facilite l’accès aux pages fréquemment utilisées sous les paramètres et aux services web associés.</p><p>Ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>, puis sélectionnez <strong>Manage custom sidebar panels</strong>. Choisissez l’icône et saisissez le titre et la destination.</p><p>Activez <strong>Admin required</strong> pour réserver l’entrée aux comptes administrateurs.</p><p>La destination peut être un chemin Home Assistant commençant par <code>/</code>, comme <code>/config/dashboard</code>, ou une URL absolue <code>http</code> ou <code>https</code>. Les autres schémas d’URL ne sont pas acceptés.</p><p>Activez <strong>Open in new tab</strong> pour ouvrir la destination dans un nouvel onglet. L’onglet Home Assistant courant revient à la page précédemment affichée. Si le navigateur bloque le nouvel onglet, UIX ouvre la destination dans l’onglet courant. Sans cette option, un site externe s’ouvre dans l’onglet courant ; les chemins Home Assistant continuent d’utiliser la navigation interne de l’application.</p><div class="info custom-block"><p class="custom-block-title">Nouvel onglet et blocage des fenêtres surgissantes</p><p>L’ouverture d’un nouvel onglet dépend de la politique du navigateur concernant les fenêtres surgissantes. UIX tente de l’ouvrir lors de la sélection du panneau, sans pouvoir le garantir. En cas de blocage, la destination s’ouvre dans l’onglet courant.</p></div><p>Chaque panneau possède une URL interne stable gérée par UIX. Vous pouvez donc modifier son titre, son icône et sa destination sans le recréer. Sa suppression retire immédiatement l’entrée de la barre latérale.</p><div class="tip custom-block"><p class="custom-block-title">Ordre de la barre latérale</p><p>Chaque utilisateur peut <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">réorganiser et masquer les entrées</a> depuis son profil.</p></div><div class="info custom-block"><p class="custom-block-title">Redirection</p><p>Un panneau personnalisé est une redirection, pas une copie de la page ni un iframe. Pour une destination interne, UIX remplace l’URL du panneau par la destination configurée afin de ne pas ajouter d’étape de redirection à l’historique du navigateur.</p></div><p>Source : <a href="https://uix.lf.technology/extras/custom-sidebar-panels/" target="_blank" rel="noreferrer">documentation originale anglaise UIX</a>, Lint-Free-Technology/uix, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p>',12)])])}const g=s(n,[["render",o]]);export{m as __pageData,g as default};
